struct CBase {
    virtual void v00();
    ~CBase();                              // 0x0099A2E0 (sets the CBase vtable; manifest label propagated)
};

struct CScriptThing : CBase {             // 12 bytes, passed by value (vtable 0x01238C8C, rtti-vtables.tsv)
    CCountedPointer PImp;                  // +4 Data / +8 Info
    ~CScriptThing() { }
