unsigned long CGameScriptInterface::GetTimeToSpendHarassingHero(CScriptThing thing)
{
    if (!thing.GetThing())
        return 0;
    CThing* pThing = thing.GetThing();
    return ((STC_5c*)pThing->GetTC((ETCInterfaceType)0xaa))->m_5c;
}

